#!/usr/bin/env python3
"""
Run this ONCE from your repo root (pathwaygh-advisor), e.g.:

    python finalize_submission.py

It writes every changed file to its exact correct path itself - no
dragging files into folders, no copy-paste. Then run finalize_check.py
to confirm each fix actually landed before you commit.
"""
import base64
import os

PAYLOAD = {'main.py': '', 'README.md': '', 'docs/evaluation.md': '', 'scripts/run_eval.py': '', 'data/raw/wassce_grading_and_admission_guide.md': ''}

def main():
    for dest, b64 in PAYLOAD.items():
        dest_path = dest.replace("/", os.sep)
        os.makedirs(os.path.dirname(dest_path) or ".", exist_ok=True)
        with open(dest_path, "wb") as f:
            f.write(base64.b64decode(b64))
        print(f"wrote {dest_path} ({len(base64.b64decode(b64))} bytes)")

    stray = os.path.join("scripts", "evaluation.md")
    if os.path.exists(stray):
        os.remove(stray)
        print(f"removed stray duplicate: {stray}")
    else:
        print(f"(no stray {stray} found - fine, already clean)")

    print()
    print("Done. Now run: python finalize_check.py")


if __name__ == "__main__":
    main()
